<script setup lang="ts">
import { ref, computed } from 'vue';import { RefreshCw, BookOpen, ArrowUpRight, ListPlus, Search, ListChecks } from 'lucide-vue-next';import { useAppStore,dateLabel } from '../store';import type { Chapter,Course } from '../../../shared/contracts';import { platforms } from '../../../shared/platforms';import PlatformMark from '../components/PlatformMark.vue';import Modal from '../components/Modal.vue'
const store=useAppStore();const selectedAccount=ref(store.accounts[0]?.id??''),query=ref(''),selectedCourse=ref<Course|null>(null),chapters=ref<Chapter[]>([]),checked=ref<string[]>([])
const filtered=computed(()=>store.courses.filter(c=>(!selectedAccount.value||c.accountId===selectedAccount.value)&&c.title.toLowerCase().includes(query.value.toLowerCase())))
async function refresh(){if(!selectedAccount.value){store.error='请先选择一个账号。';return}const a=store.accounts.find(a=>a.id===selectedAccount.value)!;const result=await store.run<number>({type:'courses.refresh',accountId:a.id});if(result!==undefined)store.toast('已读取 '+result+' 门课程');else store.workbench(a.platform)}
async function open(c:Course){store.workbench(c.platform);await store.run({type:'course.open',courseId:c.id})}
async function read(c:Course){const opened=await store.run({type:'course.open',courseId:c.id});if(opened===undefined)return;const list=await store.run<Chapter[]>({type:'course.chapters',courseId:c.id});if(list){chapters.value=list;checked.value=list.filter(x=>x.completion!=='complete').map(x=>x.id);selectedCourse.value=c}}
async function add(){if(!selectedCourse.value||!checked.value.length)return;const result=await store.run({type:'task.add',courseId:selectedCourse.value.id,chapterIds:checked.value},'已加入所属平台队列，前往任务中心开始');if(result!==undefined)selectedCourse.value=null}
</script>
<template><div class="page"><div class="page-heading"><div><p class="eyebrow">MY COURSES</p><h1>我的课程</h1><p class="subtitle">从已登录的个人课程页读取，不混入公开目录或演示课程。</p></div><button class="button primary" :disabled="!!store.busy||!store.accounts.length" @click="refresh"><RefreshCw :size="16" :class="{spin:!!store.busy}"/>刷新所选账号</button></div>
 <div class="filter-bar"><label class="field inline-field"><span>本地账号</span><select v-model="selectedAccount"><option v-if="!store.accounts.length" value="">请先添加账号</option><option v-for="a in store.accounts" :key="a.id" :value="a.id">{{platforms.find(p=>p.id===a.platform)?.name}} · {{a.label}}</option></select></label><label class="search-field"><Search :size="17"/><input v-model="query" placeholder="搜索课程名称" aria-label="搜索课程"/></label></div>
 <div class="info-banner compact-banner"><BookOpen :size="18"/><p>当前三个平台均待真实课程验证。无法识别时会明确提示，不会自动伪造课程或进度。</p></div>
 <div v-if="!filtered.length" class="empty-state panel"><div class="empty-symbol"><BookOpen :size="35"/></div><h2>{{query?'没有匹配的课程':'把你的第一门课程带进来'}}</h2><p>先添加账号并登录，再在学习工作台进入平台的「我的课程」，<br>回到这里点击刷新，读取你实际拥有的课程。</p><button class="button primary-soft" @click="store.navigate(store.accounts.length?'workbench':'accounts')">{{store.accounts.length?'打开学习工作台':'前往添加账号'}}<ArrowUpRight :size="16"/></button></div>
 <div v-else class="course-grid"><article v-for="c in filtered" :key="c.id" class="panel course-card"><div class="course-cover" :style="{'--course-color':platforms.find(p=>p.id===c.platform)?.color}"><BookOpen :size="48"/><PlatformMark :platform="c.platform" small/></div><div class="course-card-body"><span class="muted">{{store.accountLabel(c.accountId)}}</span><h3>{{c.title}}</h3><p class="course-status"><span :class="['badge',c.completion==='complete'?'green':'neutral']">{{c.completion==='complete'?'平台标记已完成':c.completion==='incomplete'?'平台标记未完成':'完成状态待确认'}}</span></p><small class="muted">读取于 {{dateLabel(c.updatedAt)}}</small><div class="course-actions"><button class="button compact" :disabled="!!store.busy" @click="open(c)"><ArrowUpRight :size="15"/>打开原页</button><button class="button primary-soft compact" :disabled="!!store.busy" @click="read(c)"><ListPlus :size="16"/>选择章节</button></div></div></article></div>
 <Modal v-if="selectedCourse" :title="selectedCourse.title+' · 选择章节'" wide @close="selectedCourse=null"><div class="chapter-toolbar"><span>{{chapters.length}} 个已识别章节</span><button class="text-button" @click="checked=chapters.filter(c=>!c.locked&&c.kind!=='manual'&&c.completion!=='complete').map(c=>c.id)">选择未完成视频 / 待识别章节</button></div><div class="chapter-list"><label v-for="(c,index) in chapters" :key="c.id" class="chapter-row"><input type="checkbox" v-model="checked" :value="c.id"/><span class="chapter-number">{{String(index+1).padStart(2,'0')}}</span><span class="grow">{{c.title}}<small v-if="c.locked||c.kind==='manual'">{{c.locked?'尚未解锁':'需要人工处理，任务将暂停'}}</small></span><span :class="['badge',c.completion==='complete'?'green':'neutral']">{{c.completion==='complete'?'平台已完成':'待确认'}}</span></label></div><p class="muted">按原章节顺序执行。遇到锁定、答题或无法确认的播放器时暂停，不自动跳过平台要求。</p><div class="modal-actions"><span class="muted grow">已选择 {{checked.length}} 个章节</span><button class="button" @click="selectedCourse=null">取消</button><button class="button primary" :disabled="!checked.length||!!store.busy" @click="add"><ListChecks :size="16"/>加入学习队列</button></div></Modal>
</div></template>
